(* [comment removed for export] *)
Definition SAVED4 (m : word -> option byte) (s : Z) (ret : word) (regs : bvmap 5 word) (fr : bvmap 5 word) : Prop :=
  rdn SEGS m (Z_to_bv 64 (s - 8)) 8 = Some (word_to_le_bytes 8 ret) /\ rdn SEGS m (Z_to_bv 64 (s - 16)) 8 = Some (word_to_le_bytes 8 (getr regs 8)) /\
  rdn SEGS m (Z_to_bv 64 (s - 24)) 8 = Some (word_to_le_bytes 8 (getr regs 9)) /\ rdn SEGS m (Z_to_bv 64 (s - 32)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (u (reg_get fr 8)))).
Lemma saved_keep : forall m m' s ret regs fr, SAVED4 m s ret regs fr -> (0 <= s - 32)%Z -> (s <= 2 ^ 64)%Z ->
  (forall a : word, (s - 32 <= u a < s)%Z -> m' a = m a) -> SAVED4 m' s ret regs fr.
